import os
import sys
import json
import time
import threading
import secrets
import requests
from flask import Flask, redirect, request as flask_request

TENSORMESH_API_KEY = os.environ.get("TENSORMESH_API_KEY")
CONTROL_PLANE_BASE = os.environ.get("TENSORMESH_CONTROL_PLANE_BASE_URL", "")
MODEL_NAME = "huihui-ai/Huihui-gemma-4-31B-it-abliterated-v2"
GPU_TYPE = "H200"
GPU_COUNT = 1
CLOUD_PROVIDER = "nebius"
REGION = "eu-north1"
REPLICAS = 1

app = Flask(__name__)

auth_state = {
    "token": None,
    "status": "pending",
    "cli_session_id": None,
    "login_url": None,
    "deployment_log": [],
    "deployment_done": False,
    "deployment_error": None,
}

_deployment_lock = threading.Lock()
_deployment_started = False


def _log(msg):
    print(msg, flush=True)
    with _deployment_lock:
        auth_state["deployment_log"].append(msg)
        if len(auth_state["deployment_log"]) > 500:
            auth_state["deployment_log"] = auth_state["deployment_log"][-500:]


def _extract_user_id(profile_json):
    if not isinstance(profile_json, dict):
        return None
    user = profile_json.get("user")
    if isinstance(user, dict) and user.get("id"):
        return user.get("id")
    if profile_json.get("id"):
        return profile_json.get("id")
    return None


def _extract_served_model_name(model_data):
    if not isinstance(model_data, dict):
        return MODEL_NAME
    for k in ("servedModelName", "served_model_name", "gatewayModelId", "gateway_model_id"):
        v = model_data.get(k)
        if isinstance(v, str) and v.strip():
            return v
    for k in ("modelName", "model_name", "modelSourceId", "model_source_id"):
        v = model_data.get(k)
        if isinstance(v, str) and v.strip():
            return v
    return MODEL_NAME


def _extract_gateway_base(model_data):
    if not isinstance(model_data, dict):
        return None
    for k in ("gatewayBaseUrl", "gateway_base_url", "gatewayBase", "gateway_base", "endpointUrl", "endpoint_url", "inferenceUrl", "inference_url"):
        v = model_data.get(k)
        if isinstance(v, str) and v.strip():
            return v.rstrip("/")
    return None


def check_api_key_auth():
    if not TENSORMESH_API_KEY:
        return None

    profile_endpoints = [
        f"{CONTROL_PLANE_BASE}/auth/profile",
        f"{CONTROL_PLANE_BASE}/v1/auth/profile",
        f"{CONTROL_PLANE_BASE}/auth/me",
        f"{CONTROL_PLANE_BASE}/v1/me",
    ]

    auth_headers_variants = [
        {"Authorization": f"Bearer {TENSORMESH_API_KEY}"},
        {"Authorization": f"Api-Key {TENSORMESH_API_KEY}"},
        {"X-API-Key": TENSORMESH_API_KEY},
        {"Authorization": f"Token {TENSORMESH_API_KEY}"},
    ]

    for endpoint in profile_endpoints:
        for auth_headers in auth_headers_variants:
            headers = {**auth_headers, "Content-Type": "application/json"}
            try:
                resp = requests.get(endpoint, headers=headers, timeout=15)
                if resp.status_code == 200:
                    print(f"  Auth succeeded: {endpoint} with {list(auth_headers.keys())[0]}", flush=True)
                    return resp.json()
            except Exception:
                pass
    return None


def start_cli_login():
    url = f"{CONTROL_PLANE_BASE}/auth/cli/start"
    try:
        resp = requests.post(url, json={}, timeout=30)
        if resp.status_code == 200:
            return resp.json()
    except Exception as e:
        print(f"Failed to start CLI login: {e}", flush=True)
    return None


def poll_cli_exchange(session_id, interval=3, timeout=300):
    url = f"{CONTROL_PLANE_BASE}/auth/cli/exchange"
    start = time.time()
    while time.time() - start < timeout:
        try:
            resp = requests.post(url, json={"cli_code": session_id}, timeout=15)
            if resp.status_code == 200:
                data = resp.json()
                access_token = data.get("accessToken", data.get("access_token", data.get("token")))
                if access_token:
                    return data
        except Exception:
            pass
        time.sleep(interval)
    return None


def get_user_profile(token):
    url = f"{CONTROL_PLANE_BASE}/auth/profile"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    try:
        resp = requests.get(url, headers=headers, timeout=30)
        if resp.status_code == 200:
            return resp.json()
    except Exception:
        pass
    return None


def get_model_status(token, model_id):
    url = f"{CONTROL_PLANE_BASE}/v1/models/{model_id}"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }
    try:
        resp = requests.get(url, headers=headers, timeout=30)
        if resp.status_code == 200:
            return resp.json()
    except Exception:
        pass
    return None


def deploy_model_with_token(token):
    url = f"{CONTROL_PLANE_BASE}/v1/models"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }

    payloads_to_try = [
        {
            "model_name": MODEL_NAME,
            "model_path": MODEL_NAME,
            "infra": {
                "cloud_provider": CLOUD_PROVIDER,
                "region": REGION,
                "gpu_type": GPU_TYPE,
                "gpu_count": GPU_COUNT,
                "replicas": REPLICAS,
                "scaling_mode": "fixed",
                "cpu_offloading": True,
            },
        },
        {
            "model_name": MODEL_NAME,
            "model_path": MODEL_NAME,
            "infra": {
                "cloud_provider": CLOUD_PROVIDER,
                "region": REGION,
                "gpu_type": GPU_TYPE,
                "gpu_count": GPU_COUNT,
                "replicas": REPLICAS,
                "scaling_mode": "fixed",
                "cpu_offloading": True,
            },
            "vllm_config": {
                "extra_args": ["--trust-remote-code"],
            },
        }
    ]

    for i, payload in enumerate(payloads_to_try, 1):
        _log(f"Deploy attempt {i}/{len(payloads_to_try)}...")
        _log(f"Payload: {json.dumps(payload, indent=2)}")
        resp = requests.post(url, headers=headers, json=payload, timeout=120)
        if resp.status_code in (200, 201):
            _log(f"Attempt {i} succeeded!")
            return resp
        _log(f"Attempt {i} failed ({resp.status_code}): {resp.text}")

    return resp


def deployment_worker(token):
    global _deployment_started
    with _deployment_lock:
        if _deployment_started:
            return
        _deployment_started = True

    _log("")
    _log("=" * 60)
    _log("STARTING DEPLOYMENT")
    _log(f"Model: {MODEL_NAME}")
    _log(f"GPU: {GPU_COUNT}x {GPU_TYPE}")
    _log(f"Provider: {CLOUD_PROVIDER} / {REGION}")
    _log("=" * 60)
    _log("")

    profile = get_user_profile(token)
    if profile:
        user_info = profile.get("user", profile) if isinstance(profile, dict) else {}
        display_name = user_info.get("displayName", user_info.get("display_name", user_info.get("email", "unknown")))
        _log(f"Authenticated as: {display_name}")
    else:
        _log("WARNING: Could not verify user profile, proceeding with deployment...")

    _log("")
    _log("Sending deployment request...")

    try:
        resp = deploy_model_with_token(token)
    except Exception as e:
        _log(f"ERROR: Deployment request exception: {e}")
        auth_state["deployment_error"] = str(e)
        auth_state["deployment_done"] = True
        return

    if resp.status_code not in (200, 201):
        _log(f"ERROR: Deployment failed. Status: {resp.status_code}")
        _log(f"Response: {resp.text}")
        auth_state["deployment_error"] = f"HTTP {resp.status_code}: {resp.text}"
        auth_state["deployment_done"] = True
        return

    try:
        deploy_result = resp.json()
    except Exception as e:
        _log(f"ERROR: Could not parse deployment response: {e}")
        _log(f"Raw response: {resp.text}")
        auth_state["deployment_error"] = f"JSON parse error: {e}"
        auth_state["deployment_done"] = True
        return

    _log("Deployment initiated!")
    _log(f"Response: {json.dumps(deploy_result, indent=2)}")

    model_id = None
    if isinstance(deploy_result, dict):
        model_id = deploy_result.get("modelId", deploy_result.get("id"))

    if not model_id:
        _log("ERROR: Could not extract model ID from deployment response.")
        auth_state["deployment_error"] = "No model ID in response"
        auth_state["deployment_done"] = True
        return

    _log(f"\nModel ID: {model_id}")
    _log("Waiting for deployment to become active...")
    _log("(Gemma 4 31B on H200 with latest transformers may take 10-25 minutes)")
    _log("")

    timeout_seconds = 3600
    poll_interval = 20
    start = time.time()

    while time.time() - start < timeout_seconds:
        status_data = get_model_status(token, model_id)
        if status_data is None:
            _log(f"  [{int(time.time() - start)}s] Failed to fetch status, retrying...")
            time.sleep(poll_interval)
            continue

        status = status_data.get("status", "unknown")
        _log(f"  [{int(time.time() - start)}s] Status: {status}")

        if isinstance(status, str) and status.lower() in ("active", "running", "served", "ready"):
            served_model_name = _extract_served_model_name(status_data)
            gateway_base = _extract_gateway_base(status_data) or ""
            user_id = _extract_user_id(profile) or "unknown"

            _log("")
            _log("=" * 60)
            _log("DEPLOYMENT IS ACTIVE!")
            _log("=" * 60)
            _log(f"\nModel ID: {model_id}")
            _log(f"Served Model Name: {served_model_name}")
            _log(f"Gateway Base URL: {gateway_base}")
            _log(f"User ID (X-User-Id): {user_id}")
            _log(f"API Key: {token[:8]}{'*' * 20}")
            _log("")
            _log("cURL example:")
            _log(f'curl -sS \\\n  -H "Authorization: Bearer {token}" \\\n  -H "X-User-Id: {user_id}" \\\n  -H "Content-Type: application/json" \\\n  "{gateway_base}/v1/chat/completions" \\\n  -d \'{{"model": "{served_model_name}", "messages": [{{"role": "user", "content": "Hello!"}}]}}\'')
            _log("")
            _log("=" * 60)

            _log("\nSending test request to verify model is responding...")
            test_url = f"{gateway_base}/v1/chat/completions"
            test_headers = {
                "Authorization": f"Bearer {token}",
                "X-User-Id": user_id,
                "Content-Type": "application/json",
            }
            test_data = {
                "model": served_model_name,
                "messages": [
                    {"role": "user", "content": "Hello! Please respond with a short greeting."}
                ],
                "max_tokens": 100,
            }
            try:
                test_resp = requests.post(test_url, headers=test_headers, json=test_data, timeout=120)
                if test_resp.status_code == 200:
                    test_result = test_resp.json()
                    content = ""
                    if isinstance(test_result, dict):
                        choices = test_result.get("choices")
                        if isinstance(choices, list) and choices:
                            msg = choices[0].get("message", {})
                            if isinstance(msg, dict):
                                content = msg.get("content", "") or ""
                    _log(f"Model test response: {content}")
                else:
                    _log(f"Test request returned status {test_resp.status_code}: {test_resp.text}")
            except Exception as e:
                _log(f"Test request failed: {e}")

            auth_state["deployment_done"] = True
            return

        if isinstance(status, str) and status.lower() in ("error", "failed", "deleted", "terminated"):
            _log(f"\nDeployment entered terminal state: {status}")
            _log(f"Details: {json.dumps(status_data, indent=2)}")
            auth_state["deployment_error"] = f"Terminal state: {status}"
            auth_state["deployment_done"] = True
            return

        time.sleep(poll_interval)

    _log(f"\nTimeout after {timeout_seconds}s waiting for deployment.")
    auth_state["deployment_error"] = f"Timeout after {timeout_seconds}s"
    auth_state["deployment_done"] = True


def _build_log_html():
    with _deployment_lock:
        lines = list(auth_state["deployment_log"])
    escaped = []
    for line in lines:
        line = line.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
        escaped.append(line)
    return "<br>".join(escaped)


@app.route("/")
def index():
    global _deployment_started

    if auth_state["token"] and _deployment_started:
        done = auth_state["deployment_done"]
        error = auth_state["deployment_error"]
        log_html = _build_log_html()

        if done and not error:
            status_msg = "<p style='color:#0f0;font-size:20px;'>DEPLOYMENT COMPLETE - Check log below for connection details.</p>"
        elif done and error:
            safe_error = error.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            status_msg = f"<p style='color:#f00;font-size:16px;'>DEPLOYMENT ERROR: {safe_error}</p>"
        else:
            status_msg = "<p style='color:#ff0;'>Deployment in progress... Page auto-refreshes every 15 seconds.</p>"

        refresh_meta = "" if done else '<meta http-equiv="refresh" content="15">'
        return f"""<!DOCTYPE html>
<html>
<head><title>TensorMesh Deployer</title>{refresh_meta}</head>
<body style="font-family: monospace; padding: 20px; background: #111; color: #0f0;">
<h1>TensorMesh Deployment</h1>
<p>Model: {MODEL_NAME}</p>
<p>GPU: {GPU_COUNT}x {GPU_TYPE}</p>
{status_msg}
<hr style="border-color:#333;">
<h2>Deployment Log</h2>
<div style="background:#000;padding:15px;border:1px solid #333;max-height:600px;overflow-y:auto;font-size:13px;line-height:1.5;">
{log_html}
</div>
</body>
</html>"""

    if TENSORMESH_API_KEY:
        profile = check_api_key_auth()
        if profile:
            auth_state["token"] = TENSORMESH_API_KEY
            auth_state["status"] = "authenticated"
            user_info = profile.get("user", profile) if isinstance(profile, dict) else {}
            display_name = user_info.get("displayName", user_info.get("display_name", user_info.get("email", "unknown")))
            threading.Thread(target=deployment_worker, args=(TENSORMESH_API_KEY,), daemon=True).start()
            return f"""<!DOCTYPE html>
